package id.imperial.resourcepack.paper;import id.imperial.resourcepack.common.*;import org.bukkit.command.*;import org.jetbrains.annotations.NotNull;
final class PaperCommand implements CommandExecutor {private final ImperialResourcePackPaper p;PaperCommand(ImperialResourcePackPaper p){this.p=p;}public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String l,String[] a){if(!s.hasPermission("imperialresourcepack.admin")){s.sendMessage("[IRP] No permission.");return true;}String x=a.length==0?"status":a[0];if(x.equalsIgnoreCase("reload"))s.sendMessage("[IRP] "+p.reload());else if(x.equalsIgnoreCase("validate"))s.sendMessage("[IRP] "+p.manager().validateActive(p.config()).message());else {ActivePack k=p.manager().active();s.sendMessage("[IRP] "+(k==null?"No active pack.":k.file().getFileName()+" | SHA-1: "+k.sha1Hex()+" | UUID: "+k.id()+" | HTTP: "+p.host().running()));}return true;}}
